const LOCALE = { en:'en-GB', tr:'tr-TR', ar:'ar-u-nu-latn', fr:'fr-FR' };   // ar: Latin digits to match the UI's numerals
let lang = (function(){ try{ const s=localStorage.getItem('irn_lang'); if(I18N[s]) return s; }catch(e){}
  const nv=(navigator.language||'').toLowerCase();
  for(const l of ['tr','ar','fr']) if(nv.startsWith(l)) return l;
  return 'en'; })();
function t(k){ const d=I18N[lang]||I18N.en; return d[k]!==undefined ? d[k] : (I18N.en[k]!==undefined ? I18N.en[k] : k); }
function applyI18n(){
  document.querySelectorAll('[data-i18n]').forEach(el=> el.textContent = t(el.getAttribute('data-i18n')));
  document.querySelectorAll('[data-i18n-html]').forEach(el=> el.innerHTML = t(el.getAttribute('data-i18n-html')));
  document.querySelectorAll('[data-i18n-ph]').forEach(el=> el.placeholder = t(el.getAttribute('data-i18n-ph')));
  document.querySelectorAll('[data-i18n-title]').forEach(el=> el.title = t(el.getAttribute('data-i18n-title')));
  document.documentElement.lang = lang;
}
function setLang(l){
  if(!I18N[l]) return;
  lang=l; try{ localStorage.setItem('irn_lang', l); }catch(e){}
  document.querySelectorAll('#langSeg button').forEach(b=> b.classList.toggle('active', b.dataset.lang===l));
  applyI18n();
  // re-render the dynamic panels in the new language
  try{ buildLegend(); }catch(e){}
  try{ renderAnnouncements(); renderDisruptionMarkers(); }catch(e){}
  try{ renderPlanLists(); updateFavBtn(); }catch(e){}
  try{ if(currentTab==='bus' && document.getElementById('busSearch')) renderBusList(document.getElementById('busSearch').value); }catch(e){}
  try{ if(currentOpts && currentOpts.length){ renderOptChips(); selectOption(currentOptIdx); } }catch(e){}
  try{ rebuildAdvRows(); }catch(e){}
  try{ renderCardSeg(); }catch(e){}
  try{ if(wxData) renderWeather(); }catch(e){}
  try{ if(selected) openStation(selected); }catch(e){}
}
